message.content:
{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "ZLFo-ycQa_rBqeMCUoXOCg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the ruined city gate.",
      "visual_description": "Crumbling stone archway with faded royal banners, twisted iron gates partly open, and broken cobblestones under a grey sky.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame eye flickers as it faces a crooked black tower with green glowing windows; Mara studies her map.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the first courtyard.",
      "visual_description": "The small metal fox winds its tail and darts across a square littered with fallen pillars and torn fabric.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver peers through a shattered window.",
      "visual_description": "A clear diving helmet reflects broken city lights as the rescuer leans into an arched window frame, seeing a dark corridor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara consults her compass at a crossroads.",
      "visual_description": "She stands under a rusting iron signpost, brass compass glowing faintly, while three paths lead deeper into ruins.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Sleeping Tax Collector is found dozing on a ledger.",
      "visual_description": "In a collapsed guardhouse, the man snores with a stamped paper stuck to his sleeve, ledger as a pillow.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Oracle Lamp illuminates a magic door.",
      "visual_description": "The lamp's glow reveals a door carved with shifting runes; Tin Fox sniffs at its base.",
      "characters": ["oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara tries to wake the Tax Collector for a key.",
      "visual_description": "She shakes the dozing official, who mumbles and turns over, papers rustling.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver swims through the magic door's reflection.",
      "visual_description": "He presses his helmet against the runes, then steps into the door's surface as if into water, disappearing.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the tower, Glass Diver finds a trapped figure.",
      "visual_description": "A dim circular room with chains hanging from the ceiling; a person in shadows lies on the floor.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Oracle Lamp spots an armored patrol approaching.",
      "visual_description": "From a broken archway, the lamp's eye sees a line of figures in dark plate armor marching across a plaza.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox leads the patrol away with a noise.",
      "visual_description": "The clockwork fox knocks over a metal barrel, then darts behind a collapsed wall, drawing the armored figures.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara marks the escape route on her map.",
      "visual_description": "She kneels by a fountain, inking a line toward a distant bridge; the Sleeping Tax Collector stirs nearby.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver emerges from the tower with the rescued person.",
      "visual_description": "He helps a dazed figure through the same magic door, stepping out onto the cobblestones.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The group reunites under a broken clock tower.",
      "visual_description": "All five characters gather; the rescued person leans on Glass Diver, while Oracle Lamp casts a steady glow.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Armored figures block the bridge.",
      "visual_description": "A stone bridge spans a dry moat, but several armored figures stand guard at the far end.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Mara and Glass Diver create a diversion with mirrors.",
      "visual_description": "They angle a shattered mirror and a pane of glass to flash blinding sunlight into the figures' eyes.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The team crosses the bridge to safety.",
      "visual_description": "All five characters hurry across the bridge as the armored figures stumble; behind them the ruined city smolders.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

